function eggDrop(eggs, floors) {
  const dp = Array.from({ length: eggs + 1 }, () => new Array(floors + 1).fill(0));
  for (let j = 1; j <= floors; j++) dp[1][j] = j;
  for (let i = 2; i <= eggs; i++) {
    for (let j = 1; j <= floors; j++) {
      dp[i][j] = Infinity;
      for (let x = 1; x <= j; x++) {
        const worst = 1 + Math.max(dp[i - 1][x - 1], dp[i][j - x]);
        dp[i][j] = Math.min(dp[i][j], worst);
      }
    }
  }
  return dp[eggs][floors];
}

